/* AIVIC_FUNCTION_BUNDLE_END owner=sendConfirmationEmailsOnReporting */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateSenderEmailFormat exports=validateSenderEmailFormat */
const __aivicBundle_46_validateSenderEmailFormat = (() => {
  function validateSenderEmailFormat(email: string): EmailValidationResult {
    // Handle null, undefined, or non-string inputs
    if (email === null || email === undefined || typeof email !== 'string') {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Handle empty string
    if (email.trim().length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for @ symbol
    if (!email.includes('@')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for spaces
    if (email.includes(' ')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Split by @ and validate parts
    const parts = email.split('@');
    
    // Should have exactly 2 parts (local and domain)
    if (parts.length !== 2) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    const [localPart, domainPart] = parts;
  
    // Check if local part (before @) is empty
    if (localPart.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check if domain part (after @) is empty
    if (domainPart.length === 0) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check if domain has at least one dot and valid structure
    if (!domainPart.includes('.')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // Check for consecutive dots or leading/trailing dots in domain
    if (domainPart.startsWith('.') || domainPart.endsWith('.') || domainPart.includes('..')) {
      return {
        isValid: false,
        error: 'Invalid email format',
      };
    }
  
    // All validations passed
    return {
      isValid: true,
    };
  }
  return { validateSenderEmailFormat };
})();
export const validateSenderEmailFormat = __aivicBundle_46_validateSenderEmailFormat.validateSenderEmailFormat;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateSenderEmailFormat */

