const __aivicBundle_57_aggregateDailyReportsWithTimestampSort = (() => {
  function aggregateDailyReportsWithTimestampSort(
    reports: Array<{
      user_id?: string;
      employee_id?: string;
      user_name?: string;
      employee_name?: string;
      yesterday_achievement?: string;
      today_plan?: string;
      issues?: string;
      issue?: string;
      submitted_at: Date;
      [key: string]: any;
    }>,
  ): Array<{
    user_id?: string;
    employee_id?: string;
    user_name?: string;
    employee_name?: string;
    yesterday_achievement?: string;
    today_plan?: string;
    issues?: string;
    issue?: string;
    submitted_at: Date;
    [key: string]: any;
  }> {
    if (!reports || reports.length === 0) {
      return [];
    }
  
    const sorted = [...reports].sort((a, b) => {
      const timeA = a.submitted_at instanceof Date ? a.submitted_at.getTime() : 0;
      const timeB = b.submitted_at instanceof Date ? b.submitted_at.getTime() : 0;
      return timeA - timeB;
    });
  
    return sorted;
  }
  return { aggregateDailyReportsWithTimestampSort };
})();
